/**
 * Bug-Fix Batch Coordinator — postJSAction for bug_fix_batch_coordinator.
 *
 * Runs as a local (no-AI) SM step for each Story in "Bug To Fix" status.
 *
 * Goal: group the Story's still-relevant open bugs into a single Epic container
 * so they can be fixed, reviewed and merged together instead of one at a time.
 *
 * What it does:
 *   1. Finds linked Bugs that are NOT Done and NOT already in a batch
 *      (label bug_fix_batch).
 *   2. Keeps only bugs that still block at least one failing Test Case
 *      (status Failed or Bug To Fix).
 *   3. Looks for an existing open batch Epic for this Story;
 *      if none exists, creates one.
 *   4. Links the selected Bugs to the Epic, labels them bug_fix_batch,
 *      and moves the Epic to Ready For Development.
 *   5. Removes the SM trigger label so the coordinator can re-run next cycle
 *      and add any newly created bugs to the same (or a new) batch.
 *
 * Bugs with the bug_fix_batch label are intentionally excluded from the
 * individual bug_development rule, so the batch agent owns them.
 */

const { LABELS } = require('./config.js');
const { extractTicketKey } = require('./common/jiraHelpers.js');
const configLoader = require('./configLoader.js');

// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
var trackersModule = require('./common/trackers.js');
var _trackerCtx = { config: null, customParams: {} };
var _trackerInst = null;
function initTracker(config, customParams) {
    _trackerCtx = { config: config || null, customParams: customParams || {} };
    _trackerInst = null;
}
function getTracker() {
    if (!_trackerInst) _trackerInst = trackersModule.createTracker(_trackerCtx.config, _trackerCtx.customParams);
    return _trackerInst;
}


var BUG_FIX_BATCH_LABEL = LABELS.BUG_FIX_BATCH || 'bug_fix_batch';

function action(params) {
    var ticketKey = params.ticket && params.ticket.key;
    var customParams = (params.jobParams && params.jobParams.customParams) || {};
    var removeLabel = customParams.removeLabel;
    var batchSize = customParams.batchSize || 5;
    var projectConfig = configLoader.loadProjectConfig(params.jobParams || params);
    initTracker(projectConfig, customParams);
    var jiraConfig = projectConfig.jira;
    var BATCH_STATUS = jiraConfig.statuses.READY_FOR_DEVELOPMENT;
    var DONE_STATUS = jiraConfig.statuses.DONE;

    function releaseLock() {
        if (ticketKey && removeLabel) {
            try {
                getTracker().removeLabel(ticketKey, removeLabel);
                console.log('Released SM lock label', removeLabel, 'from', ticketKey);
            } catch (e) {
                console.warn('Failed to remove SM lock label:', e);
            }
        }
    }

    function extractIssues(result) {
        if (!result) return [];
        if (Array.isArray(result)) return result;
        if (typeof result === 'string') {
            try {
                return extractIssues(JSON.parse(result));
            } catch (e) {
                return [];
            }
        }
        if (Array.isArray(result.issues)) return result.issues;
        if (Array.isArray(result.results)) return result.results;
        if (Array.isArray(result.data)) return result.data;
        return [];
    }

    function searchIssues(jql, fields, maxResults) {
        try {
            var result = getTracker().searchIssues(jql, { maxResults: maxResults || 50, fields: fields || ['key', 'status', 'summary', 'labels'] });
            return extractIssues(result);
        } catch (e) {
            console.warn('JQL search failed:', jql, e);
            return [];
        }
    }

    function getProjectKey() {
        return (ticketKey && ticketKey.split('-')[0]) || 'TS';
    }

    function findCandidateBugs(storyKey) {
        // Only group bugs that have not been individually picked up yet.
        // In Development / In Progress bugs are left for the single-bug pipeline.
        // JQL text: provider-specific query (WIQL on ado)
        var jql = 'issue in linkedIssues("' + storyKey + '") AND issuetype = Bug ' +
            'AND status in ("' + jiraConfig.statuses.BACKLOG + '", "' + jiraConfig.statuses.TODO + '", "' + jiraConfig.statuses.READY_FOR_DEVELOPMENT + '") ' +
            'AND (labels is EMPTY OR labels NOT IN ("' + BUG_FIX_BATCH_LABEL + '")) ' +
            'ORDER BY created ASC';
        return searchIssues(jql, ['key', 'status', 'summary', 'labels']);
    }

    function findExistingBatchEpic(storyKey) {
        // JQL text: provider-specific query (WIQL on ado)
        var jql = 'issue in linkedIssues("' + storyKey + '") AND issuetype = Epic ' +
            'AND labels in ("' + BUG_FIX_BATCH_LABEL + '") ' +
            'AND status != "' + DONE_STATUS + '" ' +
            'ORDER BY created ASC';
        var epics = searchIssues(jql, ['key', 'status', 'summary', 'labels'], 1);
        return epics.length > 0 ? epics[0] : null;
    }

    function bugStillRelevant(bugKey) {
        // JQL text: provider-specific query (WIQL on ado)
        // gh-916: 'Failed' / 'Bug To Fix' can be tag-only on Test Case (restricted ADO workflows).
        // 'label' mode widens each status to (status OR stage label) through the shared
        // {stage.KEY:Literal} placeholder (configLoader.interpolateStagePlaceholders, agents#855) in the
        // syntax of the tracker in use; the 'none' default sends the exact status-only clause as before.
        var failedName = jiraConfig.statuses.FAILED;
        var bugToFixName = jiraConfig.statuses.BUG_TO_FIX;
        var statusClause = 'status in ("' + failedName + '", "' + bugToFixName + '")';
        if (getTracker().stageFallback() === 'label') {
            statusClause = configLoader.interpolateStagePlaceholders(
                '({stage.FAILED:' + failedName + '} OR {stage.BUG_TO_FIX:' + bugToFixName + '})',
                projectConfig, getTracker().provider());
        }
        var jql = 'issue in linkedIssues("' + bugKey + '") AND issuetype = "Test Case" AND ' + statusClause;
        var tcs = searchIssues(jql, ['key', 'status'], 1);
        return tcs.length > 0;
    }

    function createBatchEpic(storyKey, projectKey, bugs) {
        var summary = 'Bug-fix batch for ' + storyKey + ' (' + bugs.length + ' bug' + (bugs.length === 1 ? '' : 's') + ')';
        var description = 'h3. 🐛 Bug-fix batch container\n\n' +
            'This Epic groups open bugs linked to *' + storyKey + '* that block failing Test Cases. ' +
            'They will be fixed, reviewed and merged in a single cycle.\n\n' +
            'h4. Linked bugs\n\n' +
            bugs.map(function(b) { return '* ' + b.key + ' — ' + (b.fields && b.fields.summary || ''); }).join('\n') + '\n\n' +
            '_Bugs are excluded from individual bug_development while they are in this batch._';

        var fieldsJson = {
            summary: summary,
            description: description,
            issuetype: { name: jiraConfig.issueTypes.EPIC || 'Epic' },
            labels: [BUG_FIX_BATCH_LABEL]
        };

        var result = getTracker().createTicketWithFields(projectKey, fieldsJson);
        var epicKey = extractTicketKey(result) || (typeof result === 'string' && result.trim()) || null; // tracker returns the key
        if (!epicKey) {
            throw new Error('Epic was created but key could not be extracted from result: ' + JSON.stringify(result));
        }
        console.log('Created batch Epic:', epicKey);

        // Relate the batch Epic to the parent Story so it is visible on both sides.
        try {
            getTracker().linkIssues(epicKey, storyKey, 'Relates');
            console.log('Linked Epic', epicKey, 'to Story', storyKey);
        } catch (e) {
            console.warn('Failed to link Epic to Story:', e);
        }

        return epicKey;
    }

    function linkBugToEpic(bugKey, epicKey) {
        getTracker().linkIssues(epicKey, bugKey, 'Relates');
        console.log('Linked bug', bugKey, 'to Epic', epicKey);
    }

    function labelBugAsBatched(bugKey) {
        getTracker().addLabel(bugKey, BUG_FIX_BATCH_LABEL);
        console.log('Added label', BUG_FIX_BATCH_LABEL, 'to', bugKey);
    }

    function moveEpicToReady(epicKey) {
        getTracker().moveToStatus(epicKey, BATCH_STATUS);
        console.log('Moved Epic', epicKey, 'to', BATCH_STATUS);
    }

    function postComments(storyKey, epicKey, bugs, isNew) {
        var bugList = bugs.map(function(b) { return '* ' + b.key; }).join('\n');
        var epicComment = 'h3. ' + (isNew ? '📦 New Bug-fix Batch Created' : '📦 Bugs Added to Existing Batch') + '\n\n' +
            'Container: *' + epicKey + '*\n' +
            'Linked bugs from *' + storyKey + '*:\n' + bugList + '\n\n' +
            'These bugs are now labeled *' + BUG_FIX_BATCH_LABEL + '* and will be handled as a single batch.';
        try {
            getTracker().postComment(epicKey, epicComment);
        } catch (e) {
            console.warn('Failed to comment on Epic:', e);
        }

        var storyComment = 'h3. 📦 Bug-fix Batch ' + (isNew ? 'Created' : 'Updated') + '\n\n' +
            'Container: *' + epicKey + '*\n' +
            'Bugs added to batch:\n' + bugList + '\n\n' +
            'The Epic has been moved to *' + BATCH_STATUS + '*.';
        try {
            getTracker().postComment(storyKey, storyComment);
        } catch (e) {
            console.warn('Failed to comment on Story:', e);
        }
    }

    try {
        if (!ticketKey) {
            throw new Error('params.ticket.key is missing');
        }
        console.log('=== Bug-fix batch coordinator for Story', ticketKey, '===');

        var candidateBugs = findCandidateBugs(ticketKey);
        console.log('Found', candidateBugs.length, 'candidate bug(s) not yet batched');

        if (candidateBugs.length === 0) {
            console.log('No unbatched open bugs — nothing to do');
            releaseLock();
            return { success: true, action: 'no_candidates', ticketKey: ticketKey };
        }

        var relevantBugs = [];
        for (var i = 0; i < candidateBugs.length; i++) {
            var bug = candidateBugs[i];
            if (bugStillRelevant(bug.key)) {
                relevantBugs.push(bug);
            } else {
                console.log('Skipping', bug.key, '- no linked failing Test Case');
            }
        }

        // Respect batch size so the PR stays reviewable.
        if (relevantBugs.length > batchSize) {
            console.log('Limiting batch to first', batchSize, 'of', relevantBugs.length, 'relevant bugs');
            relevantBugs = relevantBugs.slice(0, batchSize);
        }

        if (relevantBugs.length === 0) {
            console.log('No relevant bugs to batch — nothing to do');
            releaseLock();
            return { success: true, action: 'no_relevant_bugs', ticketKey: ticketKey };
        }

        console.log('Selected', relevantBugs.length, 'bug(s) for batch:', relevantBugs.map(function(b){return b.key;}).join(', '));

        var existingEpic = findExistingBatchEpic(ticketKey);
        var epicKey = existingEpic ? existingEpic.key : null;
        var isNew = false;

        if (!epicKey) {
            epicKey = createBatchEpic(ticketKey, getProjectKey(), relevantBugs);
            isNew = true;
        } else {
            console.log('Using existing batch Epic:', epicKey);
        }

        for (var j = 0; j < relevantBugs.length; j++) {
            var bugKey = relevantBugs[j].key;
            try {
                linkBugToEpic(bugKey, epicKey);
            } catch (e) {
                console.warn('Failed to link bug', bugKey, 'to Epic', epicKey, ':', e);
                // Continue with the rest; don't fail the whole batch for one link error.
            }
            try {
                labelBugAsBatched(bugKey);
            } catch (e) {
                console.warn('Failed to label bug', bugKey, ':', e);
            }
        }

        try {
            moveEpicToReady(epicKey);
        } catch (e) {
            console.warn('Failed to move Epic to Ready For Development:', e);
        }

        postComments(ticketKey, epicKey, relevantBugs, isNew);
        releaseLock();

        console.log('✅ Bug-fix batch coordinator complete for', ticketKey, '-> Epic', epicKey);
        return {
            success: true,
            action: isNew ? 'batch_created' : 'batch_updated',
            storyKey: ticketKey,
            epicKey: epicKey,
            batchedBugs: relevantBugs.map(function(b){ return b.key; })
        };

    } catch (error) {
        console.error('❌ Error in createBugFixBatchEpic:', error);
        releaseLock();
        return { success: false, error: error.toString() };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action };
}

/**
 * Post Bug Creation Action (postJSAction for bug_creation agent)
 *
 * Reads outputs/bug_decision.json written by the AI:
 *   { "action": "link", "existingKey": "PROJ-XXX" }
 *   { "action": "create", "summary": "...", "description": "outputs/bug_description.md" }
 *   { "action": "none", "reason": "..." }
 *
 * For link/create: links/creates bug, moves TC to "Bug To Fix", removes trigger labels.
 * For none:        posts comment, moves TC to In Rework, removes trigger labels.
 *
 * Link direction: Bug "blocks" TC (TC is blocked by the Bug until it's fixed).
 */

const { LABELS } = require('./config.js');
const configLoader = require('./configLoader.js');
const tokenUsageComment = require('./common/tokenUsageComment.js');
const trackersModule = require('./common/trackers.js');

function readFile(path) {
    try {
        var content = file_read({ path: path });
        return (content && content.trim()) ? content : null;
    } catch (e) {
        return null;
    }
}

function readDecisionJson() {
    try {
        var raw = readFile('outputs/bug_decision.json');
        if (!raw) return null;
        return JSON.parse(raw);
    } catch (e) {
        console.error('Failed to parse bug_decision.json:', e);
        return null;
    }
}

function extractKeyFromResult(result) {
    if (!result) return null;
    if (typeof result === 'string') {
        // jira_create_ticket_basic returns a JSON string: {"id":"...","key":"PROJ-123",...}
        try {
            var parsed = JSON.parse(result);
            if (parsed && parsed.key) return parsed.key;
        } catch (e) {}
        // fallback: try /browse/ URL pattern
        var urlMatch = result.match(/\/browse\/([A-Z]+-\d+)/);
        if (urlMatch) return urlMatch[1];
        // tracker.createTicket already returns the bare key (e.g. PROJ-123 or an ADO id)
        return /^[A-Za-z0-9_.#\/-]+$/.test(result.trim()) ? result.trim() : null;
    }
    return result.key || null;
}

function linkBugToTC(tracker, ticketKey, bugKey) {
    // Bug "blocks" TC: sourceKey=TC, anotherKey=Bug, relationship='Blocks'
    // → Bug is the blocker, TC is blocked (TC cannot pass until bug is fixed)
    tracker.linkIssues(ticketKey, bugKey, 'Blocks');
    console.log('✅ Linked:', bugKey, 'blocks', ticketKey);
}

function moveFailedTcToRework(tracker, ticketKey, jiraConfig) {
    tracker.moveToStatus(ticketKey, jiraConfig.statuses.IN_REWORK);
    console.log('🔧 Moved', ticketKey, 'to', jiraConfig.statuses.IN_REWORK);
    try {
        tracker.removeLabel(ticketKey, 'sm_test_automation_triggered');
        console.log('✅ Removed sm_test_automation_triggered');
    } catch (e) {}
}

function action(params) {
    var tracker;
    try {
        var ticketKey = params.ticket.key;
        var projectConfig = configLoader.loadProjectConfig(params.jobParams || params);
        var jiraConfig = projectConfig.jira;
        tracker = trackersModule.createTracker(projectConfig, (params.jobParams && params.jobParams.customParams) || params.customParams || {});
        console.log('=== Processing bug creation decision for', ticketKey, '===');

        var customParams = params.jobParams && params.jobParams.customParams;
        var smTriggerLabel = customParams && customParams.removeLabel;

        var wipLabel = params.metadata && params.metadata.contextId
            ? params.metadata.contextId + '_wip'
            : 'bug_creation_wip';

        var decision = readDecisionJson();
        if (!decision) {
            tracker.postComment(ticketKey, 'h3. ⚠️ Bug Creation Error\n\nCould not read bug_decision.json. Check workflow logs.');
            try { tracker.removeLabel(ticketKey, wipLabel); } catch (e) {}
            // KEEP sm_bug_creation_triggered label — TC stays in Failed, removing
            // the label would cause SM to re-trigger in an infinite loop.
            return { success: false, error: 'No bug_decision.json' };
        }

        console.log('Decision:', decision.action, decision.existingKey || decision.summary || '');

        var bugKey = null;
        var comment = '';
        var bugLinked = false;

        if (decision.action === 'link' && decision.existingKey) {
            // Link to existing bug
            bugKey = decision.existingKey;
            try {
                linkBugToTC(tracker, ticketKey, bugKey);
                bugLinked = true;
                comment = 'h3. 🔗 Existing Bug Linked\n\n' +
                    'Found matching bug: *' + bugKey + '*\n\n' +
                    (decision.reason ? '_' + decision.reason + '_' : '');
            } catch (e) {
                console.warn('Failed to link existing bug:', e);
                comment = 'h3. ⚠️ Bug Link Failed\n\n' +
                    'Found matching bug *' + bugKey + '* but could not create link: ' + e;
            }

        } else if (decision.action === 'create') {
            // Create new bug
            var summary = decision.summary;
            var descriptionPath = decision.description;
            var description = (descriptionPath ? readFile(descriptionPath) : null)
                || decision.descriptionText
                || summary;

            if (!summary) {
                tracker.postComment(ticketKey, 'h3. ⚠️ Bug Creation Skipped\n\nNo summary provided in bug_decision.json.');
                try { tracker.removeLabel(ticketKey, wipLabel); } catch (e) {}
                // KEEP sm_bug_creation_triggered — TC stays Failed, prevent re-fire loop.
                return { success: false, error: 'No bug summary' };
            }

            try {
                var projectKey = ticketKey.split('-')[0];
                var result = tracker.createTicket(projectKey, 'Bug', summary, description);
                bugKey = extractKeyFromResult(result);

                if (bugKey) {
                    linkBugToTC(tracker, ticketKey, bugKey);
                    bugLinked = true;
                    comment = 'h3. 🐛 New Bug Created\n\n' +
                        'Created: *' + bugKey + '*\n' +
                        '*Summary*: ' + summary + '\n\n' +
                        (decision.reason ? '_' + decision.reason + '_' : '');
                } else {
                    comment = 'h3. ⚠️ Bug Created (key not extracted)\n\nBug was created but key could not be parsed from result.';
                }
            } catch (e) {
                console.error('Failed to create bug:', e);
                comment = 'h3. ❌ Bug Creation Failed\n\n{code}' + e.toString() + '{code}';
            }

        } else if (decision.action === 'tests_pass') {
            // Tests are currently passing — ticket status is stale, move to Passed
            comment = 'h3. ✅ Tests Passing — Moving to Passed\n\n' +
                (decision.reason || 'All tests passed in the most recent run — the underlying issue has been fixed.') +
                '\n\n_Ticket status was stale. TC automatically moved to *Passed*._';

            try { tracker.postComment(ticketKey, comment); } catch (e) {}
            try {
                // gh-916: PASSED can be tag-only (restricted ADO workflows) — stage-label fallback.
                var passMove = tracker.moveToStatusOrMark(ticketKey, jiraConfig.statuses.PASSED, 'PASSED');
                if (passMove.moved || passMove.marked) {
                    console.log('✅ Tests pass — moved', ticketKey, 'to', jiraConfig.statuses.PASSED);
                }
            } catch (e) {
                console.warn('Failed to move to Passed:', e);
            }
            try { tracker.removeLabel(ticketKey, wipLabel); } catch (e) {}
            if (smTriggerLabel) {
                try { tracker.removeLabel(ticketKey, smTriggerLabel); } catch (e) {}
            }
            return { success: true, ticketKey: ticketKey, bugKey: null, action: 'tests_pass' };

        } else {
            // action: none — test code issue, not an app bug
            comment = 'h3. ℹ️ No Bug Created\n\n' +
                (decision.reason || 'AI determined no bug creation or linking is required.') +
                '\n\n_TC moved to *In Rework* so the test automation can be fixed instead of staying in *Failed*._';

            try { tracker.postComment(ticketKey, comment); } catch (e) {}
            moveFailedTcToRework(tracker, ticketKey, jiraConfig);
            try { tracker.removeLabel(ticketKey, wipLabel); } catch (e) {}
            if (smTriggerLabel) {
                try { tracker.removeLabel(ticketKey, smTriggerLabel); } catch (e) {}
            }
            console.log('ℹ️ No product bug for', ticketKey, '— moved to In Rework for test automation fixes');
            return { success: true, ticketKey: ticketKey, bugKey: null, action: 'none' };
        }

        // Post Jira comment
        try {
            tracker.postComment(ticketKey, comment);
        } catch (e) {
            console.warn('Failed to post Jira comment:', e);
        }

        // Move TC to Bug To Fix after successful link or create
        if (bugLinked) {
            try {
                // gh-916: BUG_TO_FIX can be tag-only (restricted ADO workflows) — stage-label fallback.
                var b2fMove = tracker.moveToStatusOrMark(ticketKey, jiraConfig.statuses.BUG_TO_FIX, 'BUG_TO_FIX');
                if (b2fMove.moved || b2fMove.marked) {
                    console.log('✅ Moved', ticketKey, 'to', jiraConfig.statuses.BUG_TO_FIX);
                }
            } catch (e) {
                console.warn('Failed to move to Bug To Fix:', e);
            }

            // Move the bug to Ready For Development so it gets picked up
            if (bugKey) {
                try {
                    tracker.moveToStatus(bugKey, jiraConfig.statuses.READY_FOR_DEVELOPMENT);
                    console.log('✅ Moved bug', bugKey, 'to', jiraConfig.statuses.READY_FOR_DEVELOPMENT);
                } catch (e) {
                    console.warn('Failed to move bug to Ready For Development:', e);
                }
            }
        }

        // Remove WIP label
        try { tracker.removeLabel(ticketKey, wipLabel); } catch (e) {}

        // Remove SM trigger label (TC is now in Bug To Fix, not Failed — rule won't re-fire anyway)
        if (smTriggerLabel) {
            try {
                tracker.removeLabel(ticketKey, smTriggerLabel);
                console.log('✅ Removed SM trigger label:', smTriggerLabel);
            } catch (e) {}
        }

        // Always remove sm_test_automation_triggered when TC reaches Bug To Fix.
        // The test automation agent leaves this label on Failed TCs — it must be
        // cleaned up here so the TC can be re-triggered after the bug is fixed.
        try {
            tracker.removeLabel(ticketKey, 'sm_test_automation_triggered');
            console.log('✅ Removed sm_test_automation_triggered');
        } catch (e) {}

        console.log('✅ Bug creation workflow complete for', ticketKey, '— bugKey:', bugKey || 'none');

        // Post token usage summary comments (e.g. [story_acceptance_criteria]: {...}) if any provider
        // wrote outputs/*_usage.json during the agent run.
        try {
            tokenUsageComment.postTokenUsageComments(ticketKey, { initiator: params.initiator, customParams: tokenUsageComment.customParamsOf(params) });
        } catch (e) {
            console.warn('Failed to post token usage comments:', e);
        }

        return { success: true, ticketKey: ticketKey, bugKey: bugKey, action: decision.action };

    } catch (error) {
        console.error('❌ Error in postBugCreation:', error);
        try {
            tracker.postComment(params.ticket.key, 'h3. ❌ Bug Creation Error\n\n{code}' + error.toString() + '{code}');
        } catch (e) {}
        // Release SM trigger label so SM can retry next cycle
        var customParamsOnErr = params.jobParams && params.jobParams.customParams;
        var smLabelOnErr = customParamsOnErr && customParamsOnErr.removeLabel;
        if (smLabelOnErr) {
            try { tracker.removeLabel(params.ticket.key, smLabelOnErr); } catch (e) {}
        }
        return { success: false, error: error.toString() };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action };
}

