/**
 * Post Bulk Bugs Creation Action (postJSAction for bulk_bugs_creation agent)
 *
 * Reads outputs/bulk_bug_decisions.json written by the AI:
 * {
 *   "processed": ["TS-984", "TS-954", "TS-909"],
 *   "newBugs": [
 *     {
 *       "summary": "...",
 *       "priority": "Medium",
 *       "descriptionFile": "outputs/bug_001_description.md",
 *       "linkedTCs": ["TS-984", "TS-954"]
 *     }
 *   ],
 *   "links": [{ "tcKey": "TS-909", "bugKey": "TS-123" }],
 *   "skipped": [{ "tcKey": "TS-YYY", "reason": "..." }]
 * }
 *
 * Safety: ONLY TCs listed in "processed" are acted upon.
 * TCs not in "processed" are left untouched (stay in Failed, no label added).
 *
 * For newBugs:  create bug, link all linkedTCs, move linkedTCs to "Bug To Fix"
 * For links:    link TC to existing bug, move TC to "Bug To Fix"
 * For skipped:  move TC to Backlog so test automation can be re-automated/reworked
 */

const { LABELS } = require('./config.js');
var feedbackLoop = require('./common/feedbackLoop.js');
var tokenUsageComment = require('./common/tokenUsageComment.js');
var configLoader = require('./configLoader.js');

// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
var trackersModule = require('./common/trackers.js');
var _trackerCtx = { config: null, customParams: {} };
var _trackerInst = null;
function initTracker(config, customParams) {
    _trackerCtx = { config: config || null, customParams: customParams || {} };
    _trackerInst = null;
}
function getTracker() {
    if (!_trackerInst) _trackerInst = trackersModule.createTracker(_trackerCtx.config, _trackerCtx.customParams);
    return _trackerInst;
}
const { JIRA_FIELDS } = require('./config.js');

function readFile(path) {
    try {
        var content = file_read({ path: path });
        return (content && content.trim()) ? content : null;
    } catch (e) {
        console.warn('Could not read file:', path, e);
        return null;
    }
}

function readDecisions() {
    try {
        var raw = readFile('outputs/bulk_bug_decisions.json');
        if (!raw) return null;
        return JSON.parse(raw);
    } catch (e) {
        console.error('Failed to parse bulk_bug_decisions.json:', e);
        return null;
    }
}

function extractKeyFromResult(result) {
    if (!result) return null;
    if (typeof result === 'string') {
        try {
            var parsed = JSON.parse(result);
            if (parsed && parsed.key) return parsed.key;
        } catch (e) {}
        var urlMatch = result.match(/\/browse\/([A-Z]+-\d+)/);
        return urlMatch ? urlMatch[1] : null;
    }
    return result.key || null;
}

function linkBugToTC(tcKey, bugKey) {
    getTracker().linkIssues(tcKey, bugKey, 'Blocks');
    console.log('  ✅ Linked:', bugKey, 'blocks', tcKey);
}

function findLinkedStoryForTC(tcKey) {
    if (!tcKey) return null;
    try {
        // JQL text: provider-specific query (WIQL on ado)
        var result = getTracker().searchIssues('issue in linkedIssues("' + tcKey + '") AND issuetype = Story', {
            fields: ['key'],
            maxResults: 1
        });
        var tickets = extractTickets(result);
        return tickets.length > 0 ? (tickets[0].key || null) : null;
    } catch (e) {
        console.warn('  ⚠️ Could not find linked Story for', tcKey, e);
        return null;
    }
}

function linkBugToStory(storyKey, bugKey) {
    try {
        getTracker().linkIssues(bugKey, storyKey, 'relates to');
        console.log('  ✅ Linked bug', bugKey, 'to Story', storyKey);
    } catch (e) {
        console.warn('  ⚠️ Could not link bug', bugKey, 'to Story', storyKey, e);
    }
}

function linkBugToStories(bugKey, linkedTCs) {
    var seen = {};
    linkedTCs.forEach(function(tcKey) {
        var storyKey = findLinkedStoryForTC(tcKey);
        if (storyKey && !seen[storyKey]) {
            seen[storyKey] = true;
            linkBugToStory(storyKey, bugKey);
        }
    });
}

function extractTickets(result) {
    if (!result) return [];
    if (Array.isArray(result)) return result;
    if (typeof result === 'string') {
        try {
            var parsed = JSON.parse(result);
            return extractTickets(parsed);
        } catch (e) {
            return [];
        }
    }
    if (Array.isArray(result.issues)) return result.issues;
    if (Array.isArray(result.data)) return result.data;
    if (Array.isArray(result.results)) return result.results;
    return [];
}

function findLinkedNonDoneBug(tcKey) {
    if (!tcKey) return null;
    try {
        // JQL text: provider-specific query (WIQL on ado)
        var result = getTracker().searchIssues('issue in linkedIssues("' + tcKey + '") AND issuetype = Bug AND status not in (Done)', {
            fields: ['key', 'summary', 'status'],
            maxResults: 1
        });
        var tickets = extractTickets(result);
        return tickets.length > 0 ? (tickets[0].key || null) : null;
    } catch (e) {
        console.warn('  ⚠️ Could not live-check linked non-Done bugs for', tcKey, e);
        return null;
    }
}

function findAnyLinkedNonDoneBug(tcKeys) {
    for (var i = 0; i < tcKeys.length; i++) {
        var bugKey = findLinkedNonDoneBug(tcKeys[i]);
        if (bugKey) return bugKey;
    }
    return null;
}

function moveToBugToFix(tcKey, jiraConfig) {
    try {
        // gh-916: BUG_TO_FIX can be tag-only (restricted ADO workflows) — stage-label fallback.
        var moveResult = getTracker().moveToStatusOrMark(tcKey, jiraConfig.statuses.BUG_TO_FIX, 'BUG_TO_FIX');
        if (moveResult.moved || moveResult.marked) {
            console.log('  📋 Moved to Bug To Fix:', tcKey);
        }
    } catch (e) {
        console.warn('  ⚠️ Could not move to Bug To Fix:', tcKey, e);
    }
}

function addTriggerLabel(tcKey, label) {
    try {
        getTracker().addLabel(tcKey, label);
    } catch (e) {
        console.warn('  ⚠️ Could not add label', label, 'to', tcKey, e);
    }
}

function postComment(tcKey, comment) {
    try {
        getTracker().postComment(tcKey, comment);
    } catch (e) {
        console.warn('  ⚠️ Could not post comment to', tcKey, e);
    }
}

function getFailedReasonFieldName(config, customParams) {
    return (customParams && customParams.failedReasonField)
        || (config && config.jira && config.jira.fields && config.jira.fields.failedReason)
        || JIRA_FIELDS.FAILED_REASON
        || 'Failed Reason';
}

function getFailedReasonForTc(tcKey, fieldName) {
    if (!tcKey || !fieldName) return '';
    try {
        var result = getTracker().getIssue(tcKey);
        var fields = result && result.fields ? result.fields : {};
        var raw = fields[fieldName];
        if (typeof raw === 'string') return raw;
        if (raw && typeof raw.value === 'string') return raw.value;
        // Fallback: dmtools may transform customfield_12345 into "Name (customfield_12345)".
        if (fieldName.indexOf('customfield_') !== -1) {
            for (var key in fields) {
                if (fields.hasOwnProperty(key) && key.indexOf(fieldName) !== -1) {
                    var v = fields[key];
                    if (typeof v === 'string') return v;
                    if (v && typeof v.value === 'string') return v.value;
                }
            }
        }
        return '';
    } catch (e) {
        console.warn('Could not read Failed Reason for', tcKey, ':', e);
        return '';
    }
}

function attachFileToBug(bugKey, filePath) {
    if (!bugKey || !filePath) return false;
    try {
        getTracker().attachFile(bugKey, filePath.split('/').pop(), filePath, 'text/markdown');
        console.log('  ✅ Attached description file to bug', bugKey, ':', filePath);
        return true;
    } catch (e) {
        console.warn('  ⚠️ Could not attach description file to bug', bugKey, ':', e);
        return false;
    }
}

function removeTriggerLabel(ticketKey, label) {
    if (!ticketKey || !label) return;
    try {
        getTracker().removeLabel(ticketKey, label);
        console.log('  🏷️ Removed SM trigger label "' + label + '" from ' + ticketKey);
    } catch (e) {
        console.warn('  ⚠️ Could not remove label', label, 'from', ticketKey, e);
    }
}

function removeProcessingLabels(tcKey, labels) {
    labels.forEach(function(label) {
        removeTriggerLabel(tcKey, label);
    });
}

function markResolved(resolvedSet, tcKey) {
    if (tcKey) resolvedSet[tcKey] = true;
}

function moveSkippedTcToBacklog(tcKey, jiraConfig) {
    getTracker().moveToStatus(tcKey, jiraConfig.statuses.BACKLOG);
    console.log('  🔧 Moved to ' + jiraConfig.statuses.BACKLOG + ':', tcKey);
    try {
        getTracker().removeLabel(tcKey, 'sm_test_automation_triggered');
    } catch (e) {}
}

function action(params) {
    try {
        var actualParams = params.jobParams || params;
        var customParams = actualParams.customParams || {};
        var triggerLabel = customParams.removeLabel || 'sm_bug_creation_triggered';
        var smTriggerLabel = customParams.smTriggerLabel || 'sm_bulk_bugs_creation_triggered';
        var projectConfig = configLoader.loadProjectConfig(actualParams);
        initTracker(projectConfig, customParams);
        var jiraConfig = projectConfig.jira;
        var failedReasonFieldName = getFailedReasonFieldName(projectConfig, customParams);

        console.log('=== Processing bulk bug creation decisions ===');

        var decisions = readDecisions();
        if (!decisions) {
            console.error('❌ Could not read bulk_bug_decisions.json — attempting recovery');

            // Remove SM trigger label so SM can re-dispatch on next run
            var triggerTicketKey = (actualParams.ticket && actualParams.ticket.key) || null;
            removeTriggerLabel(triggerTicketKey, smTriggerLabel);

            // Try feedback loop resume — tell agent to produce the output file
            var resume = feedbackLoop.resumeAgent({
                ticketKey: triggerTicketKey || 'unknown',
                customParams: customParams,
                section: 'postAction',
                stage: 'bulk_bugs_output',
                error: 'The AI agent did not produce the required outputs/bulk_bug_decisions.json file. ' +
                    'The file must be valid JSON with keys: processed (array of TC keys), ' +
                    'newBugs (array of bug definitions with summary, priority, descriptionFile, linkedTCs), ' +
                    'links (array of {tcKey, bugKey} for existing bugs), ' +
                    'skipped (array of {tcKey, reason}). ' +
                    'Read input/failed_tcs.json and input/open_bugs.json, then write the decisions file.'
            });

            if (resume.attempted) {
                console.log('🔄 Feedback loop resumed agent — re-running post-action');
                return action(params);
            }

            return { success: false, error: 'Missing bulk_bug_decisions.json, resume not attempted: ' + (resume.reason || 'unknown') };
        }

        var processed = decisions.processed || [];
        var newBugs = decisions.newBugs || [];
        var links = decisions.links || [];
        var skipped = decisions.skipped || [];
        var fixedByBug = decisions.fixedByBug || [];

        if (fixedByBug.length > 0) {
            console.error('❌ fixedByBug is not supported for bulk bug creation; Done bugs are excluded from matching');
            fixedByBug.forEach(function(fixDef) {
                if (fixDef && fixDef.tcKey) {
                    removeProcessingLabels(fixDef.tcKey, [triggerLabel, smTriggerLabel]);
                }
            });
            return {
                success: false,
                error: 'fixedByBug is not supported; create or link a non-Done bug, or skip only confirmed test-code issues'
            };
        }

        console.log('Decisions: ' + newBugs.length + ' new bugs, ' + links.length + ' links, ' +
            skipped.length + ' skipped');
        console.log('Processed TCs: ' + processed.join(', '));

        var results = { created: [], linked: [], skipped: [], released: [], errors: [] };

        // Build a set of processed TC keys for safety check
        var processedSet = {};
        processed.forEach(function(k) { processedSet[k] = true; });
        var resolvedSet = {};

        // ── 1. Create new bugs and link their TCs ─────────────────────────────
        newBugs.forEach(function(bugDef, idx) {
            var summary = bugDef.summary;
            if (!summary) {
                console.warn('  ⚠️ Skipping newBug[' + idx + '] — no summary');
                return;
            }

            var linkedTCs = bugDef.linkedTCs || [];

            var description = null;
            if (bugDef.descriptionFile) {
                description = readFile(bugDef.descriptionFile);
                if (!description) {
                    console.warn('  ⚠️ descriptionFile not found:', bugDef.descriptionFile, '— using Failed Reason as fallback');
                }
            }
            if (!description && linkedTCs.length > 0) {
                var failedReason = getFailedReasonForTc(linkedTCs[0], failedReasonFieldName);
                if (failedReason) {
                    description = failedReason;
                    console.log('  ℹ️ Using Failed Reason from', linkedTCs[0], 'as bug description fallback');
                }
            }
            if (!description) {
                description = summary;
            }

            console.log('  Creating bug:', summary, '| links to:', linkedTCs.join(', '));

            var existingBugKey = findAnyLinkedNonDoneBug(linkedTCs);
            if (existingBugKey) {
                console.log('  🔁 Existing linked non-Done bug found during live re-check:', existingBugKey);
                linkedTCs.forEach(function(tcKey) {
                    if (!processedSet[tcKey]) {
                        console.warn('  ⚠️ TC', tcKey, 'not in processed list — skipping (safety guard)');
                        return;
                    }
                    try {
                        linkBugToTC(tcKey, existingBugKey);
                        moveToBugToFix(tcKey, jiraConfig);
                        removeProcessingLabels(tcKey, [triggerLabel, smTriggerLabel]);
                        postComment(tcKey,
                            'h3. 🔗 Existing Bug Linked (Batch Live Re-check)\n\n' +
                            'Linked to existing non-Done bug: *' + existingBugKey + '*'
                        );
                        results.linked.push({ tcKey: tcKey, bugKey: existingBugKey, source: 'live_recheck' });
                        markResolved(resolvedSet, tcKey);
                    } catch (e) {
                        console.error('  ❌ Failed to link', tcKey, '→', existingBugKey, ':', e);
                        results.errors.push({ tcKey: tcKey, bugKey: existingBugKey, error: e.toString() });
                    }
                });

                // Link the existing bug to the parent Story(ies) of the linked TCs
                linkBugToStories(existingBugKey, linkedTCs);
                return;
            }

            var bugKey = null;
            try {
                var projectKey = (linkedTCs[0] || 'TS-1').split('-')[0];
                var priority = bugDef.priority || 'Medium';
                var result = getTracker().createTicket(projectKey, 'Bug', summary, description);
                bugKey = (typeof result === 'string' && /^[A-Za-z0-9_-]+$/.test(result)) ? result : extractKeyFromResult(result);
            } catch (e) {
                console.error('  ❌ Failed to create bug:', e);
                results.errors.push({ summary: summary, error: e.toString() });
                return;
            }

            if (!bugKey) {
                console.warn('  ⚠️ Bug created but key could not be extracted for:', summary);
                results.errors.push({ summary: summary, error: 'key not extracted' });
                return;
            }

            console.log('  🐛 Created bug:', bugKey);

            // Attach the description file to the new bug if it exists
            if (bugDef.descriptionFile) {
                attachFileToBug(bugKey, bugDef.descriptionFile);
            }

            // Link each TC to the new bug
            linkedTCs.forEach(function(tcKey) {
                if (!processedSet[tcKey]) {
                    console.warn('  ⚠️ TC', tcKey, 'not in processed list — skipping (safety guard)');
                    return;
                }
                try {
                    linkBugToTC(tcKey, bugKey);
                    moveToBugToFix(tcKey, jiraConfig);
                    removeProcessingLabels(tcKey, [triggerLabel, smTriggerLabel]);
                    postComment(tcKey,
                        'h3. 🐛 New Bug Created (Batch)\n\n' +
                        'Created: *' + bugKey + '*\n' +
                        '*Summary*: ' + summary
                    );
                    results.created.push({ tcKey: tcKey, bugKey: bugKey });
                    markResolved(resolvedSet, tcKey);
                } catch (e) {
                    console.error('  ❌ Failed to process TC', tcKey, ':', e);
                    results.errors.push({ tcKey: tcKey, bugKey: bugKey, error: e.toString() });
                }
            });

            // Also link the new bug to the parent Story(ies) of the linked TCs
            linkBugToStories(bugKey, linkedTCs);
        });

        // ── 2. Link TCs to existing bugs ─────────────────────────────────────
        links.forEach(function(linkDef) {
            var tcKey = linkDef.tcKey;
            var bugKey = linkDef.bugKey;

            if (!tcKey || !bugKey) {
                console.warn('  ⚠️ Invalid link entry:', JSON.stringify(linkDef));
                return;
            }
            if (!processedSet[tcKey]) {
                console.warn('  ⚠️ TC', tcKey, 'not in processed list — skipping (safety guard)');
                return;
            }

            console.log('  Linking', tcKey, '→', bugKey);
            try {
                linkBugToTC(tcKey, bugKey);
                moveToBugToFix(tcKey, jiraConfig);
                removeProcessingLabels(tcKey, [triggerLabel, smTriggerLabel]);
                postComment(tcKey,
                    'h3. 🔗 Existing Bug Linked (Batch)\n\n' +
                    'Linked to existing bug: *' + bugKey + '*'
                );
                results.linked.push({ tcKey: tcKey, bugKey: bugKey });
                markResolved(resolvedSet, tcKey);
            } catch (e) {
                console.error('  ❌ Failed to link', tcKey, '→', bugKey, ':', e);
                results.errors.push({ tcKey: tcKey, bugKey: bugKey, error: e.toString() });
            }

            // Ensure the existing bug is also linked to the parent Story of this TC
            linkBugToStories(bugKey, [tcKey]);
        });

        // ── 3. Test-code issues → Backlog so they leave Failed and can be re-automated ─
        skipped.forEach(function(skipDef) {
            var tcKey = skipDef.tcKey;
            if (!tcKey) return;
            if (!processedSet[tcKey]) {
                console.warn('  ⚠️ TC', tcKey, 'not in processed list — skipping (safety guard)');
                return;
            }
            console.log('  Skipping', tcKey, '—', skipDef.reason || 'no reason given');
            moveSkippedTcToBacklog(tcKey, jiraConfig);
            try {
                removeProcessingLabels(tcKey, [triggerLabel, smTriggerLabel]);
                console.log('  🏷️ Removed trigger labels from', tcKey, '— eligible for re-automation');
            } catch (e) {}
            postComment(tcKey,
                'h3. ℹ️ No Bug Created (Batch) — Test Code Issue\n\n' +
                '*Reason*: ' + (skipDef.reason || 'AI determined this is a test code issue, not an application bug.') +
                '\n\n_TC moved to *Backlog* so the test automation can be reworked instead of staying in *Failed*._'
            );
            results.skipped.push({ tcKey: tcKey, reason: skipDef.reason });
            markResolved(resolvedSet, tcKey);
        });

        // ── 4. Recovery guard: processed TCs must never keep a stale bulk lock ──
        processed.forEach(function(tcKey) {
            if (!tcKey || resolvedSet[tcKey]) return;

            console.warn('  ⚠️ Processed TC has no successful bulk outcome:', tcKey);
            var linkedBugKey = findLinkedNonDoneBug(tcKey);
            if (linkedBugKey) {
                moveToBugToFix(tcKey, jiraConfig);
                removeProcessingLabels(tcKey, [triggerLabel, smTriggerLabel]);
                postComment(tcKey,
                    'h3. 🔗 Existing Bug Found After Batch\n\n' +
                    'Bulk bug creation did not produce a final decision for this TC, ' +
                    'but a linked non-Done bug already exists: *' + linkedBugKey + '*.\n\n' +
                    '_TC moved to *Bug To Fix* and stale bug-creation locks were removed._'
                );
                results.linked.push({ tcKey: tcKey, bugKey: linkedBugKey, source: 'post_batch_recovery' });
                markResolved(resolvedSet, tcKey);
                return;
            }

            removeProcessingLabels(tcKey, [triggerLabel, smTriggerLabel]);
            postComment(tcKey,
                'h3. ⚠️ Bulk Bug Creation Released\n\n' +
                'Bulk bug creation processed this TC but did not create, link, or skip it. ' +
                'No linked non-Done bug was found during the post-action live check.\n\n' +
                '_Stale bug-creation locks were removed so the next bulk cycle can retry from Failed._'
            );
            results.released.push({ tcKey: tcKey, reason: 'no bulk outcome and no linked non-Done bug' });
        });

        // ── Summary ───────────────────────────────────────────────────────────
        console.log('=== Bulk bug creation complete ===');
        console.log('  Created:', results.created.length, 'bug links');
        console.log('  Linked:', results.linked.length, 'to existing bugs');
        console.log('  Skipped:', results.skipped.length);
        console.log('  Released:', results.released.length, 'without outcome');
        console.log('  Errors:', results.errors.length);

        // Post token usage summary comments (e.g. [story_acceptance_criteria]: {...}) if any provider
        // wrote outputs/*_usage.json during the agent run.
        try {
            tokenUsageComment.postTokenUsageComments((actualParams.ticket && actualParams.ticket.key) || null, { initiator: actualParams.initiator, customParams: tokenUsageComment.customParamsOf(params) });
        } catch (e) {
            console.warn('Failed to post token usage comments:', e);
        }

        return { success: true, results: results };

    } catch (e) {
        console.error('postBulkBugsCreation failed:', e);
        throw e;
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action };
}

/**
 * Create planned follow-up stories from outputs/stories.json.
 *
 * Reusable post-action helper for workflows where the CLI agent produces an
 * intake-compatible story plan that should be materialized in Jira.
 */

const { ISSUE_TYPES, STATUSES } = require('./config.js');
const trackersModule = require('./common/trackers.js');
const { setTicketPriority } = require('./common/jiraHelpers.js');
const { buildSummary } = require('./common/aiResponseParser.js');

// Tracker for the current action() run (built inside action(), never at module load).
var tracker = null;

function tryReadFile(path) {
    try {
        return file_read(path);
    } catch (e) {
        try {
            return file_read({ path: path });
        } catch (e2) {
            return '';
        }
    }
}

function readStoriesJson(path) {
    var raw = tryReadFile(path);
    if (!raw || !raw.trim()) {
        return { found: false, stories: [] };
    }

    try {
        var parsed = JSON.parse(raw);
        if (!Array.isArray(parsed)) {
            return { found: true, stories: [], error: 'stories.json is not an array' };
        }
        return { found: true, stories: parsed };
    } catch (error) {
        return { found: true, stories: [], error: 'stories.json is invalid JSON: ' + error };
    }
}

function readDescriptionFile(filePath, fallbackSummary) {
    if (!filePath) {
        return fallbackSummary || '';
    }

    var content = tryReadFile(filePath);
    return (content && content.trim()) ? content : (fallbackSummary || '');
}

function getSourceLabels(params) {
    return (params.ticket && params.ticket.fields && params.ticket.fields.labels) ? params.ticket.fields.labels : [];
}

function resolveTargetKey(target, params) {
    if (target === 'sourceTicket') {
        return params.ticket && params.ticket.key ? params.ticket.key : null;
    }

    if (target === 'sourceParent') {
        return params.ticket && params.ticket.fields && params.ticket.fields.parent
            ? params.ticket.fields.parent.key
            : null;
    }

    return null;
}

function getDefaultParentKey(params, config) {
    if (config.defaultParentKey) {
        return config.defaultParentKey;
    }

    if (config.defaultParentSource) {
        return resolveTargetKey(config.defaultParentSource, params);
    }

    if (config.defaultParentFromSourceParent) {
        return resolveTargetKey('sourceParent', params);
    }

    return null;
}

function getSourcePriorityName(params) {
    var priority = params && params.ticket && params.ticket.fields ? params.ticket.fields.priority : null;
    if (!priority) return null;
    if (typeof priority === 'string') return priority;
    return priority.name || null;
}

function normalizePriorityName(priority) {
    if (!priority) return null;
    if (typeof priority === 'string') return priority;
    return priority.name || null;
}

function resolveStoryPriority(entry, params, config) {
    var entryPriority = entry ? normalizePriorityName(entry.priority) : null;
    if (entryPriority) {
        return entryPriority;
    }

    var defaultPriority = config ? normalizePriorityName(config.defaultPriority) : null;
    if (defaultPriority) {
        return defaultPriority;
    }

    if (config && config.inheritSourcePriority === false) {
        return null;
    }

    return getSourcePriorityName(params);
}

function getJiraIssueTypeName(config) {
    return (config && config.issueTypeName) ? config.issueTypeName : ISSUE_TYPES.STORY;
}

function isStoryEntry(entry) {
    return !entry.type || entry.type === ISSUE_TYPES.STORY || entry.type === 'Story';
}

function fetchExistingStoriesByParent(parentKey, issueTypeName) {
    var summaryToKey = {};
    if (!parentKey) return summaryToKey;

    // JQL text: provider-specific query (WIQL on ado)
    var issues = tracker.searchIssues('parent = ' + parentKey + ' AND issuetype = "' + issueTypeName + '" ORDER BY created ASC', {
        fields: ['key', 'summary']
    }) || [];

    for (var i = 0; i < issues.length; i++) {
        var issue = issues[i];
        var summary = issue && issue.fields ? issue.fields.summary : '';
        if (summary) {
            summaryToKey[summary] = issue.key;
        }
    }

    return summaryToKey;
}

function createStory(entry, resolvedParentKey, params, config) {
    var summary = buildSummary(entry.summary, 0);
    var description = readDescriptionFile(entry.description, summary);
    var projectKey = config.projectKey || resolvedParentKey.split('-')[0];
    var priority = resolveStoryPriority(entry, params, config);
    var issueTypeName = getJiraIssueTypeName(config);

    var fieldsJson = {
        summary: summary,
        description: description,
        issuetype: { name: issueTypeName },
        parent: { key: resolvedParentKey }
    };

    if (priority) {
        fieldsJson.priority = { name: priority };
    }

    var createdKey = tracker.createTicketWithFields(projectKey, fieldsJson);
    if (!createdKey) {
        throw new Error('Could not extract Jira key from create response');
    }

    if (priority) {
        setTicketPriority(createdKey, priority, tracker);
    }

    if (entry.storyPoints != null && !isNaN(entry.storyPoints)) {
        tracker.updateField(createdKey, 'Story Points', Number(entry.storyPoints));
    }

    return createdKey;
}

function linkToSource(createdKey, sourceKey, relationship) {
    if (!createdKey || !sourceKey || !relationship) return;

    tracker.linkIssues(createdKey, sourceKey, relationship);
}

function linkStory(createdKey, params, config, isExisting) {
    if (!createdKey) return;

    var links = [];

    if (config.linkToSourceRelationship) {
        links.push({
            target: 'sourceTicket',
            relationship: config.linkToSourceRelationship,
            includeExisting: true
        });
    }

    if (Array.isArray(config.additionalLinks)) {
        links = links.concat(config.additionalLinks);
    }

    for (var i = 0; i < links.length; i++) {
        var link = links[i] || {};
        if (!link.relationship) continue;
        if (isExisting && link.includeExisting === false) continue;

        var targetKey = link.targetKey || resolveTargetKey(link.target, params);
        if (!targetKey) continue;

        try {
            linkToSource(createdKey, targetKey, link.relationship);
        } catch (error) {
            console.warn('Failed to create link from ' + createdKey + ' to ' + targetKey + ':', error);
        }
    }
}

function buildSummaryComment(results, title) {
    var created = results.filter(function(r) { return r.success && !r.existing; });
    var reused = results.filter(function(r) { return r.success && r.existing; });
    var failed = results.filter(function(r) { return !r.success; });

    var lines = [
        'h3. *' + (title || 'Planned Stories') + '*',
        ''
    ];

    if (created.length === 0 && reused.length === 0 && failed.length === 0) {
        lines.push('_No follow-up stories were processed._');
        return lines.join('\n');
    }

    if (created.length > 0) {
        lines.push('*Created:*');
        created.forEach(function(item) {
            lines.push('* ' + item.key + ' - ' + item.summary);
        });
        lines.push('');
    }

    if (reused.length > 0) {
        lines.push('*Reused Existing:*');
        reused.forEach(function(item) {
            lines.push('* ' + item.key + ' - ' + item.summary);
        });
        lines.push('');
    }

    if (failed.length > 0) {
        lines.push('*Failed:*');
        failed.forEach(function(item) {
            lines.push('* ' + item.summary + ' - ' + item.error);
        });
        lines.push('');
    }

    lines.push('*Total Processed:* ' + (created.length + reused.length));
    return lines.join('\n');
}

function action(params) {
    try {
        var jobParams = params.jobParams || {};
        var customParams = (params.customParams) || (jobParams.customParams) || {};
        var config = customParams.storyPlanCreation || {};
        tracker = trackersModule.createTracker(null, customParams);
        var sourceTicketKey = params.ticket && params.ticket.key;
        var sourceLabels = getSourceLabels(params);

        if (config.enabled === false) {
            return { success: true, skipped: true, message: 'storyPlanCreation disabled' };
        }

        if (!sourceTicketKey) {
            return { success: false, error: 'Missing source ticket key' };
        }

        var skipLabelPresent = config.skipIfLabel && sourceLabels.indexOf(config.skipIfLabel) !== -1;
        var skipIfLabelMode = config.skipIfLabelMode || 'strict';
        if (skipLabelPresent && skipIfLabelMode !== 'reuse') {
            console.log('Story plan creation skipped for ' + sourceTicketKey + ' because label "' + config.skipIfLabel + '" is present');
            return { success: true, skipped: true, message: 'Skip label present' };
        }
        if (skipLabelPresent) {
            console.log('Story plan label "' + config.skipIfLabel + '" is present on ' + sourceTicketKey + ', continuing in reuse mode');
        }

        var outputFile = config.outputFile || 'outputs/stories.json';
        var parsed = readStoriesJson(outputFile);
        if (parsed.error) {
            return { success: false, error: parsed.error };
        }

        if (!parsed.found) {
            if (config.required) {
                return { success: false, error: outputFile + ' not found or empty' };
            }
            console.log(outputFile + ' not found — skipping planned story creation');
            return { success: true, skipped: true, message: 'No story plan file found' };
        }

        var stories = parsed.stories || [];
        if (stories.length === 0) {
            console.log(outputFile + ' contains no planned stories');
            return { success: true, createdTickets: [], message: 'No planned stories to create' };
        }

        var defaultParentKey = getDefaultParentKey(params, config);
        var issueTypeName = getJiraIssueTypeName(config);
        var existingByParent = {};
        var keyMap = {};
        var results = [];

        for (var i = 0; i < stories.length; i++) {
            var entry = stories[i] || {};
            var summary = buildSummary(entry.summary, i);
            var resolvedParentKey = entry.parent || defaultParentKey;

            if (!isStoryEntry(entry)) {
                results.push({
                    type: entry.type || 'Unknown',
                    summary: summary,
                    key: null,
                    success: false,
                    error: 'Unsupported entry type for story plan: ' + (entry.type || '(missing)')
                });
                continue;
            }

            if (!resolvedParentKey) {
                results.push({
                    type: ISSUE_TYPES.STORY,
                    summary: summary,
                    key: null,
                    success: false,
                    error: 'No parent key resolved for story'
                });
                continue;
            }

            if (!existingByParent[resolvedParentKey]) {
                existingByParent[resolvedParentKey] = fetchExistingStoriesByParent(resolvedParentKey, issueTypeName);
            }

            var existingKey = existingByParent[resolvedParentKey][summary] || null;
            if (existingKey) {
                entry._createdKey = existingKey;
                if (entry.tempId) keyMap[entry.tempId] = existingKey;
                keyMap[existingKey] = existingKey;
                linkStory(existingKey, params, config, true);
                results.push({
                    type: ISSUE_TYPES.STORY,
                    summary: summary,
                    key: existingKey,
                    success: true,
                    existing: true
                });
                continue;
            }

            try {
                var createdKey = createStory(entry, resolvedParentKey, params, config);
                entry._createdKey = createdKey;
                existingByParent[resolvedParentKey][summary] = createdKey;
                if (entry.tempId) keyMap[entry.tempId] = createdKey;
                keyMap[createdKey] = createdKey;
                linkStory(createdKey, params, config, false);

                results.push({
                    type: ISSUE_TYPES.STORY,
                    summary: summary,
                    key: createdKey,
                    success: true,
                    existing: false
                });
            } catch (error) {
                entry._createdKey = null;
                results.push({
                    type: ISSUE_TYPES.STORY,
                    summary: summary,
                    key: null,
                    success: false,
                    error: error.toString()
                });
            }
        }

        function resolveKey(ref) {
            return keyMap[ref] || null;
        }

        for (var j = 0; j < stories.length; j++) {
            var story = stories[j];
            var blockedKey = story._createdKey;
            if (!blockedKey || !Array.isArray(story.blockedBy)) continue;

            var anyBlocked = false;
            var blockedByRelationship = config.blockedByRelationship || 'Blocks';
            for (var b = 0; b < story.blockedBy.length; b++) {
                var blockerKey = resolveKey(story.blockedBy[b]);
                if (!blockerKey) continue;
                try {
                    tracker.linkIssues(blockedKey, blockerKey, blockedByRelationship);
                    anyBlocked = true;
                } catch (e) {
                    console.warn('Failed to create ' + blockedByRelationship + ' link between ' + blockerKey + ' and ' + blockedKey + ':', e);
                }
            }

            if (anyBlocked && config.blockedStatusName !== false) {
                try {
                    tracker.moveToStatus(blockedKey, config.blockedStatusName || STATUSES.BLOCKED);
                } catch (statusError) {
                    console.warn('Failed to move ' + blockedKey + ' to Blocked:', statusError);
                }
            }
        }

        for (var k = 0; k < stories.length; k++) {
            var storyForLinking = stories[k];
            var storyKey = storyForLinking._createdKey;
            if (!storyKey || !Array.isArray(storyForLinking.integrates)) continue;

            for (var l = 0; l < storyForLinking.integrates.length; l++) {
                var otherKey = resolveKey(storyForLinking.integrates[l]);
                if (!otherKey || otherKey === storyKey) continue;
                try {
                    tracker.linkIssues(storyKey, otherKey, 'Relates');
                } catch (e) {
                    console.warn('Failed to create Relates link between ' + storyKey + ' and ' + otherKey + ':', e);
                }
            }
        }

        var successfulCount = results.filter(function(item) { return item.success; }).length;
        var failureCount = results.filter(function(item) { return !item.success; }).length;

        if (config.postSummaryComment !== false) {
            try {
                tracker.postComment(sourceTicketKey, buildSummaryComment(results, config.summaryCommentTitle || 'Planned Follow-up Stories'));
            } catch (commentError) {
                console.warn('Failed to post story plan summary comment to ' + sourceTicketKey + ':', commentError);
            }
        }

        if (successfulCount > 0 && config.addLabel) {
            try {
                tracker.addLabel(sourceTicketKey, config.addLabel);
            } catch (labelError) {
                console.warn('Failed to add label "' + config.addLabel + '" to ' + sourceTicketKey + ':', labelError);
            }
        }

        return {
            success: failureCount === 0,
            createdTickets: results,
            message: 'Processed ' + successfulCount + ' planned stor' + (successfulCount === 1 ? 'y' : 'ies') +
                (failureCount ? ', ' + failureCount + ' failed' : '')
        };
    } catch (error) {
        console.error('Error in createPlannedStoriesFromOutput:', error);
        return { success: false, error: error.toString() };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action: action };
}

