            var entry = stories[i] || {};
            var summary = buildSummary(entry.summary, i);
            var resolvedParentKey = entry.parent || defaultParentKey;

            if (!isStoryEntry(entry)) {
                results.push({
                    type: entry.type || 'Unknown',
                    summary: summary,
                    key: null,
                    success: false,
