            metadata: { contextId: 'bug_creation' },
            jobParams: {
                customParams: {
                    removeLabel: 'sm_bug_creation_triggered'
                }
            }
        });

        assert.equal(result.success, true);
        assert.equal(result.action, 'none');
        assert.deepEqual(statusMoves, [
            { key: 'TS-222', statusName: 'In Rework' }
