                return extractIssues(JSON.parse(result));
            } catch (e) {
                return [];
            }
        }
        if (Array.isArray(result.issues)) return result.issues;
        if (Array.isArray(result.results)) return result.results;
        if (Array.isArray(result.data)) return result.data;
        return [];
