Decision handlers:
```js
function handleLinkDecision(ctx, decision) {
   var bugKey = decision.existingKey;
   var linked = tryLinkBugToTc(ctx, bugKey);
   var comment = linked.ok ? buildLinkedComment(bugKey, decision.reason) : buildLinkFailedComment(bugKey, linked.error);
   return finishLinkedOutcome(ctx, { bugKey: bugKey, bugLinked: linked.ok, comment: comment, action: 'link' });
