function extractKeyFromResult(result) {
    if (!result) return null;
    if (typeof result === 'string') {
        // jira_create_ticket_basic returns a JSON string: {"id":"...","key":"PROJ-123",...}
        try {
            var parsed = JSON.parse(result);
