        assert.deepEqual(r.calls.moves, []);
        assert.deepEqual(r.calls.removedLabels, [
            { key: 'TS-101', label: 'bug_creation_wip' },
            { key: 'TS-101', label: 'sm_bug_creation_triggered' },
