        });

        assert.equal(result.success, true);
        assert.deepEqual(result.batchedBugs, ['BUG-1']);
        assert.equal(labels.length, 1);
    });

    test('returns no_candidates and releases the lock when there is nothing to batch', function() {
        var created = [];
