        ]);
        assert.equal(comments.length, 2);
        assert.contains(comments[0].comment, 'New Bug-fix Batch Created');
        assert.contains(comments[1].comment, 'Moved Epic to *Ready For Development*'.replace('Moved Epic to *', 'The Epic has been moved to *'));
    });

    test('adds relevant bugs to an existing open batch Epic instead of creating one', function() {
        var created = [];
        var links = [];
        var labels = [];
        var moves = [];

