        jira_create_ticket_with_json: function() { return ''; },
        file_read: function() { return null; }
    };

    var allMocks = Object.assign({}, defaults, mocks);
    return loadModule(
        'js/createBugFixBatchEpic.js',
        makeRequire({
            './config.js': configModule,
            './configLoader.js': makeDefaultConfigLoaderMock(),
            './common/jiraHelpers.js': loadModule('js/common/jiraHelpers.js', makeRequire({ './config.js': configModule }), allMocks),
