function findLinkedStoryForTC(tcKey) {
    if (!tcKey) return null;
    try {
        // JQL text: provider-specific query (WIQL on ado)
        var result = getTracker().searchIssues('issue in linkedIssues("' + tcKey + '") AND issuetype = Story', {
            fields: ['key'],
