        return tickets.length > 0 ? (tickets[0].key || null) : null;
    } catch (e) {
        console.warn('  ⚠️ Could not live-check linked non-Done bugs for', tcKey, e);
        return null;
    }
}

function findAnyLinkedNonDoneBug(tcKeys) {
    for (var i = 0; i < tcKeys.length; i++) {
