                type: 'Story',
                summary: '[SF] Salesforce implementation story',
                description: 'outputs/stories/sf_story.md',
                priority: 'Medium',
                blockedBy: ['mobile-story']
            }
        ]);

        var m = loadStoryPlanAction({
            file_read: function(arg) {
